      msg  = '登入逾期，請重新登入';
      icon = 'lock';
    } else if (status === 403 && e?.message?.includes('campus')) {
      msg  = '您的帳號尚未設定校區，請聯絡主任';
      icon = 'manage_accounts';
    } else if (status === 403) {
      msg  = '無存取權限，請聯絡管理員';
      icon = 'lock';
    } else if (!navigator.onLine || !status) {
      msg  = '網路連線異常，請確認後重試';
      icon = 'wifi_off';
    } else {
      msg  = '伺服器異常，請稍後重試';
      icon = 'error';
