public function typing(Request $request, $threadId)
{
    $userId = $this->resolveUserId($request);
    if (!$userId) {
        return response()->json(['message' => 'Unauthorized'], 401);
    }

    $threadId = (int) $threadId;
    $campusIds = $this->resolveCampusIds($request);

    if (!ChatService::threadInCampus($threadId, $campusIds)) {
        return response()->json(['message' => 'Not found'], 404);
    }
    if (!ChatService::isMember($threadId, $userId)) {
        return response()->json(['message' => 'Forbidden'], 403);
    }

    $isTyping = (bool) $request->input('typing', true);
    $user     = $request->attributes->get('auth_user');
    $userName = $user->Name ?? 'Unknown';

    try {
        broadcast(new ChatTyping($threadId, $userId, $userName, $isTyping))->toOthers();
    } catch (\Throwable $e) {
        \Illuminate\Support\Facades\Log::warning('[Chat] Typing broadcast failed: ' . $e->getMessage());
    }

    return response()->json(['ok' => true]);
}

