const typingUsers = ref([]); // [{ user_id, user_name }]
let typingTimeouts = {};      // user_id → timer
let typingThrottleTimer = null;
let typingDebounceTimer = null;

function handleTypingEvent(data) {
  const uid = data.user_id;
  if (data.is_typing) {
    if (!typingUsers.value.find(u => u.user_id === uid)) {
      typingUsers.value.push({ user_id: uid, user_name: data.user_name });
    }
    if (typingTimeouts[uid]) clearTimeout(typingTimeouts[uid]);
    typingTimeouts[uid] = setTimeout(() => {
      typingUsers.value = typingUsers.value.filter(u => u.user_id !== uid);
      delete typingTimeouts[uid];
    }, 3000);
  } else {
    typingUsers.value = typingUsers.value.filter(u => u.user_id !== uid);
    if (typingTimeouts[uid]) { clearTimeout(typingTimeouts[uid]); delete typingTimeouts[uid]; }
  }
}

function onInputTyping() {
  if (!activeThread.value) return;
  // Throttle: send typing.start at most once per 300ms
  if (!typingThrottleTimer) {
    sendTyping(activeThread.value.id, true).catch(() => {});
    typingThrottleTimer = setTimeout(() => { typingThrottleTimer = null; }, 300);
  }
  // Debounce: send typing.stop after 2s of no input
  if (typingDebounceTimer) clearTimeout(typingDebounceTimer);
  typingDebounceTimer = setTimeout(() => {
    sendTyping(activeThread.value.id, false).catch(() => {});
    typingDebounceTimer = null;
  }, 2000);
}

function clearTypingTimers() {
  if (typingThrottleTimer) { clearTimeout(typingThrottleTimer); typingThrottleTimer = null; }
  if (typingDebounceTimer) { clearTimeout(typingDebounceTimer); typingDebounceTimer = null; }
  Object.values(typingTimeouts).forEach(clearTimeout);
  typingTimeouts = {};
  typingUsers.value = [];
}

// ── Message search ───────────────────────────────────────────────
const searchOpen        = ref(false);
const searchQuery       = ref('');
const searchResultIndex = ref(0);
const searchInputEl     = ref(null);

const searchResults = computed(() => {
  const q = searchQuery.value.trim().toLowerCase();
  if (!q || q.length < 1) return [];
  return sortedMessages.value
    .map((msg, idx) => ({ idx, msg }))
    .filter(({ msg }) => msg.body && msg.body.toLowerCase().includes(q))
    .map(({ idx }) => idx);
});

function isSearchMatch(msg) {
  const q = searchQuery.value.trim().toLowerCase();
  if (!q) return false;
  return msg.body && msg.body.toLowerCase().includes(q);
}

function highlightText(body) {
  if (!body) return '';
  const q = searchQuery.value.trim();
  if (!q) return escapeHtml(body);
  const regex = new RegExp(escapeRegex(q), 'gi');
  return escapeHtml(body).replace(regex, m => `<mark class="search-hl">${m}</mark>`);
}

function escapeHtml(str) {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function toggleSearch() {
  searchOpen.value = !searchOpen.value;
  if (searchOpen.value) {
    nextTick(() => searchInputEl.value?.focus());
  } else {
    searchQuery.value = '';
  }
}

function closeSearch() {
  searchOpen.value  = false;
  searchQuery.value = '';
}

function searchNext() {
  if (!searchResults.value.length) return;
  searchResultIndex.value = (searchResultIndex.value + 1) % searchResults.value.length;
  scrollToSearchResult();
}

function searchPrev() {
  if (!searchResults.value.length) return;
  searchResultIndex.value = (searchResultIndex.value - 1 + searchResults.value.length) % searchResults.value.length;
  scrollToSearchResult();
}

function scrollToSearchResult() {
  const targetIdx = searchResults.value[searchResultIndex.value];
  const msg = sortedMessages.value[targetIdx];
  if (!msg) return;
  const el = msgRowRefs[msg.id];
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

watch(searchResults, () => {
  searchResultIndex.value = 0;
  if (searchResults.value.length) scrollToSearchResult();
});

