$dt       = ($segEnd - $segStart) / 60.0;
$maxLevel = max(array_column($concurrent, 'level_weight'));

// PRD §4.3 v1.4: 以 lr_id 最小者作為 tie-break 主導者，
// 避免同層級重疊時每筆 LR 各自保留基礎薪（重複計算）。
// 主導者：最高層且 lr_id 最小 → 得 (n-1)*bonus*dt 加給。
// 非主導者（同層非 primary 或低層）：重疊段扣 base_rate*dt，
// 相當於基本費歸 0（最終由 buildSessionRow 的 max(0, ...) 保底）。
$maxLevelLrIds = [];
foreach ($concurrent as $c) {
    if ($c['level_weight'] === $maxLevel) {
        $maxLevelLrIds[] = $c['lr_id'];
    }
}
$primaryLrId = !empty($maxLevelLrIds) ? min($maxLevelLrIds) : null;

if ($iv['level_weight'] === $maxLevel && $iv['lr_id'] === $primaryLrId) {
    $lrNet += ($lrCount - 1) * $bonusPerStudent * $dt;
} else {
    $lrNet -= $iv['base_rate'] * $dt;
}

