/**
 * 計算一堂課的薪資時數。
 *
 * 業務規則（見 docs/AI_REGRESSION_LESSONS.md «薪資計算以契約時長為準»）：
 *   薪資時數以客約排定時長為準，不以 LR 實際 StartTime/EndTime 縮放。
 *   主任在「備註 / 調整時段」微調實際上課時間，不應影響老師薪資。
 *
 * 優先順序：
 *   1. resolveSessionDurationForWeekday($isoWeekday)  （每日不同時長的課程）
 *   2. StudentClass->SessionDuration                    （全週統一時長）
 *   3. 實際 StartTime/EndTime                            （fallback，當合約欄位缺失）
 *   4. 2.0h default
 */
private function calcHours(?string $startTime, ?string $endTime, $studentClass = null, ?string $sessionDate = null): float
{
    if ($studentClass) {
        if ($sessionDate && method_exists($studentClass, 'resolveSessionDurationForWeekday')) {
            try {
                $iso = (int) \Carbon\Carbon::parse($sessionDate)->isoWeekday();
                if ($iso > 0) {
                    $dur = (int) $studentClass->resolveSessionDurationForWeekday($iso);
                    if ($dur >= 30) {
                        return $dur / 60.0;
                    }
                }
            } catch (\Throwable $ignored) {}
        }
        $fallback = (int) ($studentClass->SessionDuration ?? 0);
        if ($fallback >= 30) {
            return $fallback / 60.0;
        }
    }
    if ($startTime && $endTime) {
        foreach (['H:i:s', 'H:i'] as $fmt) {
            $subLen = $fmt === 'H:i:s' ? 8 : 5;
            try {
                $s = \Carbon\Carbon::createFromFormat($fmt, substr($startTime, 0, $subLen));
                $e = \Carbon\Carbon::createFromFormat($fmt, substr($endTime,   0, $subLen));
                if ($e > $s) {
                    return $e->diffInMinutes($s) / 60.0;
                }
            } catch (\Exception $ignored) {}
        }
    }
    return 2.0; // default fallback: 2h per session
}

