/**
 * 回傳一筆 LearningRecord 對應的契約時長（分鐘）。
 * 優先 resolveSessionDurationForWeekday，其次 SessionDuration，
 * 若皆不可用則回 0（由呼叫端決定 fallback）。
 */
private function contractedDurationMinutes($lr): int
{
    $sc = $lr->studentClass ?? null;
    if (!$sc) {
        return 0;
    }
    $sessionDate = $lr->SessionDate ?? null;
    if ($sessionDate && method_exists($sc, 'resolveSessionDurationForWeekday')) {
        try {
            $iso = (int) \Carbon\Carbon::parse($sessionDate)->isoWeekday();
            if ($iso > 0) {
                $dur = (int) $sc->resolveSessionDurationForWeekday($iso);
                if ($dur >= 30) {
                    return $dur;
                }
            }
        } catch (\Throwable $ignored) {}
    }
    $fallback = (int) ($sc->SessionDuration ?? 0);
    return $fallback >= 30 ? $fallback : 0;
}

