 *   2) PUT  /api/v1/student-classes/{id} (paid_at / payment_status)
 *   3) Invoice payment recording
 *
 * Historical bug: recomputeCounters cleared Paid=0 whenever RemainingSessions<=2.
 * This clobbered the paid state set at creation for short courses (1–2 sessions)
 * or after any deduction (sign-in, retro-leave, LR approve, backfill).
 */
public function test_sync_counters_does_not_clear_paid_when_remaining_lte_2(): void
{
    $student = $this->createStudent();
    $sc = $this->createStudentClass($student->id, [
        'Paid' => 1,
        'PayDate' => '2026-04-17',
        'SessionCount' => 2,
        'RemainingSessions' => 2,
        'UsedSessions' => 0,
    ]);

    \App\Services\SessionDeductionService::syncCounters($sc);

    $sc->refresh();
    $this->assertSame(1, (int) $sc->Paid, 'syncCounters must NOT clear Paid when RemainingSessions <= 2');
    $this->assertNotNull($sc->PayDate, 'syncCounters must NOT clear PayDate');
}

