 * must persist Paid=1, and GET /api/v1/student-classes must return
 * payment_status="paid". Previously SessionDeductionService::recomputeCounters
 * cleared Paid=0 whenever RemainingSessions<=2, hiding the user's input.
 */
public function test_create_course_with_paid_at_shows_paid_status(): void
{
    $token = $this->createDirectorToken([1], 'director-paid-at-a@example.com');
    $teacherId = $this->createTeacher(1, 'teacher-paid-at-a@example.com');
    $student = $this->createStudent(1, '建立課程繳費日期A');

    $future1 = now()->copy()->addDays(7);
    while ((int) $future1->dayOfWeekIso !== 2) { $future1->addDay(); }
    $future2 = $future1->copy()->addWeek();

    $res = $this->withHeaders([
        'Authorization' => "Bearer {$token}",
        'Accept' => 'application/json',
    ])->postJson('/api/v1/class-sessions/batch', [
        'branch_id' => 1,
        'student_id' => $student->id,
        'teacher_id' => $teacherId,
        'subject' => 'Math',
        'class_type' => 'one_on_one',
        'total_classes' => 8,
        'confirmed_dates' => [],
        'future_dates' => [$future1->toDateString(), $future2->toDateString()],
        'days_of_week' => [2],
        'start_time' => '16:00',
        'duration_minutes' => 120,
        'price_per_session' => 500,
        'payment_type' => 'session',
        'paid_at' => '2026-04-17',
    ]);

    $res->assertCreated();
    $studentClassId = (int) ($res->json('student_class_id') ?? 0);
    $this->assertTrue($studentClassId > 0);

    $this->assertDatabaseHas('StudentClass', [
        'ID' => $studentClassId,
        'Paid' => 1,
    ]);

    $list = $this->withHeaders([
        'Authorization' => "Bearer {$token}",
        'Accept' => 'application/json',
    ])->getJson('/api/v1/student-classes?branch_id=1&student_id=' . $student->id);

    $list->assertOk();
    $row = collect($list->json('data') ?? [])->firstWhere('id', $studentClassId);
    $this->assertNotNull($row, 'Created course must appear in list');
    $this->assertSame('paid', (string) ($row['payment_status'] ?? ''));
}

